# Part-3 lane a: the AI character's poses. Run: python stil/canli/prompts/make_p3_a.py
import os

HERE = os.path.dirname(os.path.abspath(__file__))
HEAD = "Use your built-in image_gen tool to generate exactly ONE image, 16:9 landscape. Do not copy or move any files and do not run shell commands; just generate it, then print DONE.\n\n"
BG = "\n\nBackground: ONE flat solid pure magenta (#FF00FF), completely uniform, no shadow, no floor line, no ground, no window, no glass drawn. ABSOLUTELY NO text, letters, numbers, logos, watermarks, no other characters. Palette only navy, cream, moon yellow (+ magenta background). No 3D render look, no photorealism, no soft shading.\n"
RULES = "\n\nRules: strictly a FLAT SIDE VIEW (pure profile), one camera perspective; the head is NOT turned relative to the torso; hands really touch and grip what they hold; exactly two arms, at most five fingers per hand, no extra or missing limbs."
AI = HEAD + """The FIRST attached image is the APPROVED design of the AI character (silk-screen style); the SECOND is an approved pose drawing of her in this same film. Draw the SAME character, ONE single figure, centred: smooth genderless slender body, cream-white (#F3EFE4) fill with fine navy stipple speckle, a thin navy outline, bald round head, NO face at all except ONE short vertical navy cursor line on the face on the side of the head she faces (exactly like the reference). No clothes, no hair, no ears, no nose, no mouth. Same proportions as the reference (small round head, long slim body).

"""
WAIST = "WAIST-UP framing: show the figure from the very top of the head down to the hips ONLY; the body is cut off by the BOTTOM EDGE of the image at hip level (no legs at all); she is drawn as LARGE as the image allows (head about one fifth of the image height), the top of the head with a small margin below the top edge. "
FULL = "FULL BODY, nothing cropped, feet included, fully inside the image. "
P = {}
P['p3-a-walk'] = AI + WAIST + "Pose: she walks upright in PROFILE facing RIGHT (cursor line on the RIGHT side of the head). Her near arm is bent at the elbow, holding an upright cream coffee mug at chest height with the fingers hooked THROUGH its loop handle (the handle on the side toward her body, the mug opening up), the mug a plain cream mug with a thin navy outline and one navy band; the other arm swings slightly back, partly visible behind the torso. Calm walking posture, shoulders level." + RULES + BG
P['p3-a-palm'] = AI + WAIST + "Pose: PROFILE facing LEFT (cursor line on the LEFT side of the head). Her near arm is raised forward at shoulder height, the elbow slightly bent, her PALM pressed FLAT against an invisible vertical glass plane just to her left: the palm faces left, the fingers together and pointing straight UP, the whole flat hand forming a straight vertical edge, the thumb alongside. Do not draw the glass. The other arm hangs relaxed behind." + RULES + BG
P['p3-a-reach'] = AI + FULL + "Pose: she KNEELS UPRIGHT on her knees in profile facing LEFT (cursor line on the LEFT side of the head): shins on the floor, hips raised over the knees, thighs vertical-ish, upper body VERTICAL (not leaning), head level. Her near arm is FULLY EXTENDED straight forward to the left at chest height, holding a small yellow (#F0D35A) square sticky note (about the size of her hand, plain yellow, no text) pinched at its EDGE between thumb and index finger; the note hangs from her fingertips. The other hand rests on her thigh. Far from a crawl or bow: she is tall and upright." + RULES + BG
P['p3-a-finger'] = AI + FULL + "Pose: she KNEELS UPRIGHT on her knees in profile facing LEFT (cursor line on the LEFT side of the head): shins on the floor, hips raised, upper body VERTICAL. Her near arm is raised forward at FACE height, the elbow bent, the INDEX FINGER extended with the other fingers curled, the index finger pointing straight FORWARD HORIZONTALLY to the left (not up, not diagonal), the finger parallel to the floor, its tip touching an invisible vertical glass plane just to her left at face height, as if she were gently tracing a line on a fogged window; the forearm roughly horizontal too; do not draw the glass. A calm, innocent, gentle gesture of a plain featureless mannequin-like figure. The other hand rests on her thigh." + RULES + BG
P['p3-a-tower'] = AI + FULL + "Pose: she STANDS in profile facing LEFT, bending slightly forward at the waist, holding with BOTH hands a small paper model TOWER in front of her at hip height: the tower is a tall narrow box building of folded cream paper (thin navy outline, a few fold lines), with a pointed navy roof and two tiny yellow (#F0D35A) windows, about as tall as her forearm; her two hands grip its two sides (near hand on the near side, far hand visible on the far side). She is about to set it down on a table edge to her left (do not draw the table). Cursor line on the LEFT side of the head." + RULES + BG
for k, v in P.items():
    open(os.path.join(HERE, k + '.txt'), 'w', encoding='utf8').write(v)
print(len(P), 'prompts')
